LUA='.local-inputs/assets-extra/android/data/scripts/'
def helper(name,signature,source,line,text,cases=(),extra_refs=(),status='NOT-NEEDED',reason=None,supplement=False):
    ev=[{'source':LUA+source,'line':line}]+[{'source':LUA+s,'line':n}for s,n in extra_refs]
    contracts[name]={'name':name,'status':status,'supplement':supplement,'lua_signature':signature,
      'behavior':[{'text':'PROVEN: '+text,'evidence':ev}],
      'gates':[{'text':'PROVEN: Lua definition/field type admission as described; not an independent engine registration.','evidence':ev}],
      'state_timers_events':[{'text':'PROVEN: Lua table/context mutation and native calls only as described.','evidence':ev}],
      'return':[{'text':'PROVEN: Lua return as described; no native C signature because this row is a Lua helper/table callback.','evidence':ev}],
      'wrapper_traces':[{'text':'PROVEN: Exact Binder public-name scan and unified original registration strings checked; '+('no exact native name found. The retained original Lua call is a distinct undefined engine-looking symbol; no alias to similarly named CF__CalcMissOrDodge is proven.' if status=='UNRESOLVED' else 'Lua definition/table field found at supplied source; real engine calls are dependencies below, not a hidden native of this spelling.'),'evidence':ev}],
      'known_answers':[{'confidence':'PROVEN','given':a,'expected':b,'evidence':ev}for a,b in cases],
      'unresolved_reasons':[reason or 'Exact original Lua definition/table field proves this ranked parser candidate is not an independent native; preserved in sealed inventory.'],
      'port_status':'MISSING','port_difference':'This Lua helper needs its authored script loaded plus its reusable native dependencies; a same-name C++ identifier or generic native registration is not its implementation. Runtime execution not verified.'}
